import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # find connected components of 2s; bounding boxes
    seen=[[False]*W for _ in range(H)]
    import collections
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and not seen[i][j]:
                q=collections.deque([(i,j)]); seen[i][j]=True; comp=[(i,j)]
                while q:
                    x,y=q.popleft()
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==2 and not seen[a][b]:
                            seen[a][b]=True; q.append((a,b)); comp.append((a,b))
                rs=[c[0] for c in comp]; cs=[c[1] for c in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                if len(comp)==(r1-r0+1)*(c1-c0+1):  # full rectangle border
                    for a in range(r0+1,r1):
                        for b in range(c0+1,c1):
                            if g[a][b]==0: g[a][b]=8
    return g
